<template>
  <div class="page-surface management-page experiment-page">
    <div class="experiment-filters">
      <a-input v-model:value="filters.keyword" allow-clear placeholder="实验编号、名称或课题" @press-enter="load" />
      <a-select v-model:value="filters.status" allow-clear placeholder="全部状态" :options="statusOptions" />
      <a-range-picker v-model:value="filters.dates" />
      <a-button type="primary" @click="load"><SearchOutlined />查询</a-button>
      <a-button v-if="has('lab:export')" @click="operationsApi.export('experiments',{keyword:filters.keyword||undefined,status:filters.status,startTime:filters.dates?.[0]?.format('YYYY-MM-DD'),endTime:filters.dates?.[1]?.format('YYYY-MM-DD')})"><DownloadOutlined />导出</a-button>
      <a-button v-if="mode==='mine'&&has('lab:experiment:create')" class="action-create" @click="openCreate"><PlusOutlined />新建实验</a-button>
    </div>
    <a-table row-key="id" bordered class="management-table" :columns="columns" :data-source="rows" :loading="loading" :pagination="{pageSize:12}" :scroll="{x:1250,y:'calc(100vh - 320px)'}">
      <template #bodyCell="{column,record}">
        <template v-if="column.key==='status'"><a-tag :color="statusColors[record.status]">{{statusNames[record.status]}}</a-tag></template>
        <template v-else-if="column.key==='resources'"><span>{{record.instruments.length}} 台仪器 · {{record.materials.length}} 种物资</span></template>
        <template v-else-if="column.key==='actions'"><a-space wrap>
          <a-button size="small" @click="openDetail(record)">详情</a-button>
          <a-button v-if="editable(record)&&record.status==='draft'" size="small" class="action-edit" @click="openEdit(record)">编辑</a-button>
          <a-button v-if="editable(record)&&record.status==='draft'" size="small" type="primary" @click="start(record)">开始</a-button>
          <a-button v-if="editable(record)&&record.status==='in_progress'" size="small" type="primary" @click="openRecord(record)">记录</a-button>
          <a-button v-if="editable(record)&&record.status==='in_progress'" size="small" @click="complete(record)">完成</a-button>
          <a-button v-if="editable(record)&&record.status==='completed'" size="small" @click="reasonAction(record,'reopen')">退回</a-button>
          <a-button v-if="editable(record)&&record.status==='completed'&&has('lab:experiment:archive')" size="small" class="action-delete" @click="archive(record)">归档</a-button>
          <a-button v-if="record.status==='archived'&&has('lab:experiment:unarchive')" size="small" class="action-edit" @click="reasonAction(record,'unarchive')">解档</a-button>
        </a-space></template>
      </template>
    </a-table>

    <a-modal v-model:open="editorOpen" :title="editing?'编辑实验草稿':'新建实验'" width="820px" @ok="save">
      <a-form layout="vertical">
        <a-row :gutter="16"><a-col :span="12"><a-form-item label="实验名称"><a-input v-model:value="form.experimentName" /></a-form-item></a-col><a-col :span="12"><a-form-item label="课题名称"><a-input v-model:value="form.topicName" /></a-form-item></a-col></a-row>
        <a-form-item label="课题组"><a-select v-model:value="form.groupId" allow-clear :options="groupOptions" /></a-form-item>
        <a-form-item label="实验目的"><a-textarea v-model:value="form.purpose" :rows="3" /></a-form-item>
        <div class="relation-block"><div class="relation-block__title">关联仪器与已通过预约</div><div v-for="(item,index) in form.instruments" :key="index" class="relation-row"><a-select v-model:value="item.instrumentId" show-search placeholder="选择仪器" :options="instrumentOptions" @change="item.bookingId=undefined" /><a-select v-model:value="item.bookingId" allow-clear placeholder="关联预约（可选）" :options="bookingOptions.filter(x=>x.instrumentId===item.instrumentId)" /><a-button danger type="text" @click="form.instruments.splice(index,1)"><DeleteOutlined /></a-button></div><a-button block @click="form.instruments.push({instrumentId:undefined,bookingId:undefined})"><PlusOutlined />添加仪器</a-button></div>
        <div class="relation-block"><div class="relation-block__title">关联物资与已通过领用单</div><div v-for="(item,index) in form.materials" :key="index" class="relation-row relation-row--material"><a-select v-model:value="item.materialId" show-search placeholder="选择物资" :options="materialOptions" @change="item.requisitionId=undefined" /><a-select v-model:value="item.requisitionId" allow-clear placeholder="关联领用单（可选）" :options="requisitionOptions.filter(x=>x.materialIds.includes(item.materialId))" /><a-input-number v-model:value="item.quantity" :min="0.0001" placeholder="数量" /><a-button danger type="text" @click="form.materials.splice(index,1)"><DeleteOutlined /></a-button></div><a-button block @click="form.materials.push({materialId:undefined,requisitionId:undefined,quantity:1})"><PlusOutlined />添加物资</a-button></div>
      </a-form>
    </a-modal>

    <a-drawer v-model:open="detailOpen" width="840" class="experiment-detail-drawer">
      <template #title><div class="drawer-title"><ExperimentOutlined /><span>实验任务详情</span><a-tag v-if="detail" :color="statusColors[detail.status]">{{statusNames[detail.status]}}</a-tag></div></template>
      <template v-if="detail">
        <section class="experiment-summary">
          <div class="experiment-summary__main"><div class="experiment-summary__number">{{detail.experimentNo}}</div><h2>{{detail.experimentName}}</h2><p>{{detail.purpose}}</p></div>
          <div class="experiment-summary__meta"><div><UserOutlined /><span>负责人</span><b :title="detail.ownerName||'-'">{{detail.ownerName||'-'}}</b></div><div><TeamOutlined /><span>课题组</span><b :title="detail.groupName||'-'">{{detail.groupName||'-'}}</b></div><div><BookOutlined /><span>课题</span><b :title="detail.topicName||'-'">{{detail.topicName||'-'}}</b></div><div><ClockCircleOutlined /><span>创建时间</span><b :title="date(detail.createTime)">{{date(detail.createTime)}}</b></div></div>
        </section>
        <a-tabs class="detail-tabs" size="large">
          <a-tab-pane key="resources"><template #tab><ExperimentOutlined />关联资源</template>
            <div class="resource-section"><div class="section-heading"><ExperimentOutlined /><div><h3>仪器与预约</h3><span>{{detail.instruments.length}} 项关联</span></div></div><div v-if="detail.instruments.length" class="resource-list"><div v-for="item in detail.instruments" :key="item.id" class="resource-row"><div class="resource-row__icon"><ExperimentOutlined /></div><div class="resource-row__body"><b>{{item.instrumentName}}</b><span>{{item.bookingNo||'未关联预约'}}</span></div><a-tag :color="item.bookingNo?'green':'default'">{{item.bookingNo?'已关联预约':'仅关联仪器'}}</a-tag></div></div><a-empty v-else :image="simpleImage" /></div>
            <div class="resource-section"><div class="section-heading"><DatabaseOutlined /><div><h3>物资与领用</h3><span>{{detail.materials.length}} 项关联</span></div></div><div v-if="detail.materials.length" class="resource-list"><div v-for="item in detail.materials" :key="item.id" class="resource-row"><div class="resource-row__icon resource-row__icon--material"><DatabaseOutlined /></div><div class="resource-row__body"><b>{{item.materialName}}</b><span>{{item.requisitionNo||'未关联领用单'}}</span></div><strong class="resource-quantity">{{item.quantity}} {{item.unitName}}</strong></div></div><a-empty v-else :image="simpleImage" /></div>
          </a-tab-pane>
          <a-tab-pane key="records"><template #tab><FileTextOutlined />实验记录 <span class="tab-count">{{detail.records.length}}</span></template>
            <div v-if="detail.records.length" class="record-stream"><article v-for="item in detail.records" :key="item.id" class="record-entry"><div class="record-entry__rail"><span :class="['record-dot',`record-dot--${item.recordType}`]"><FileTextOutlined /></span></div><div class="record-entry__content"><header><div><a-tag :color="recordColors[item.recordType]||'default'">{{recordNames[item.recordType]||item.recordType}}</a-tag><b>{{item.creatorName||'未知用户'}}</b></div><time><ClockCircleOutlined />{{date(item.recordTime)}}</time></header><p>{{item.content}}</p></div></article></div><div v-else class="detail-empty"><FileTextOutlined /><span>暂无实验记录</span></div>
          </a-tab-pane>
          <a-tab-pane key="files"><template #tab><PaperClipOutlined />实验附件 <span class="tab-count">{{detail.files.length}}</span></template>
            <div class="attachment-toolbar"><div><h3>实验附件</h3><p>图片、PDF、表格、文档及文本数据</p></div><a-upload v-if="detail.status!=='archived'&&editable(detail)" :show-upload-list="false" :before-upload="upload" accept=".jpg,.jpeg,.png,.pdf,.csv,.xlsx,.docx,.txt"><a-button type="primary"><UploadOutlined />上传附件</a-button></a-upload><a-tag v-else color="default"><LockOutlined />只读</a-tag></div>
            <div v-if="detail.files.length" class="attachment-list"><div v-for="item in detail.files" :key="item.id" class="attachment-row"><div class="attachment-row__icon"><FileTextOutlined /></div><div class="attachment-row__body"><b :title="item.originalName">{{item.originalName}}</b><span>{{fileType(item.originalName)}} · {{fileSize(item.fileSize)}} · {{date(item.createTime)}}</span></div><a-tooltip title="下载附件"><a-button type="text" shape="circle" class="attachment-download" @click="experimentApi.download(item.id,item.originalName)"><DownloadOutlined /></a-button></a-tooltip></div></div><div v-else class="detail-empty detail-empty--files"><PaperClipOutlined /><span>暂无实验附件</span></div>
          </a-tab-pane>
        </a-tabs>
      </template>
    </a-drawer>
    <a-modal v-model:open="recordOpen" title="新增实验记录" @ok="saveRecord"><a-form layout="vertical"><a-form-item label="记录类型"><a-select v-model:value="recordForm.recordType" :options="recordTypes" /></a-form-item><a-form-item label="记录内容"><a-textarea v-model:value="recordForm.content" :rows="6" /></a-form-item></a-form></a-modal>
  </div>
</template>
<script setup lang="ts">
import {operationsApi} from '../../api/operations';
import {computed,h,onMounted,reactive,ref,watch} from 'vue';import {BookOutlined,ClockCircleOutlined,DatabaseOutlined,DeleteOutlined,DownloadOutlined,ExperimentOutlined,FileTextOutlined,LockOutlined,PaperClipOutlined,PlusOutlined,SearchOutlined,TeamOutlined,UploadOutlined,UserOutlined} from '@ant-design/icons-vue';import {Empty,message,Modal} from 'ant-design-vue';import {experimentApi} from '../../api/experiment';import {instrumentApi} from '../../api/instrument';import {inventoryApi} from '../../api/inventory';import {labFoundationApi} from '../../api/lab';import {useAuthStore} from '../../stores/auth';import type {ExperimentDto} from '../../types/experiment';
const props=defineProps<{mode:'mine'|'query'}>();const mode=computed(()=>props.mode),auth=useAuthStore(),rows=ref<ExperimentDto[]>([]),loading=ref(false),editorOpen=ref(false),editing=ref<ExperimentDto|null>(null),detailOpen=ref(false),detail=ref<ExperimentDto|null>(null),recordOpen=ref(false),recordTarget=ref<ExperimentDto|null>(null);const filters=reactive<any>({keyword:'',status:undefined,dates:null}),form=reactive<any>({}),recordForm=reactive({recordType:'process',content:''});const groups=ref<any[]>([]),instruments=ref<any[]>([]),bookings=ref<any[]>([]),materials=ref<any[]>([]),requisitions=ref<any[]>([]);
const simpleImage=Empty.PRESENTED_IMAGE_SIMPLE;const columns:any[]=[{title:'实验编号',dataIndex:'experimentNo',width:210},{title:'实验名称',dataIndex:'experimentName'},{title:'课题',dataIndex:'topicName'},{title:'负责人',dataIndex:'ownerName',width:110},{title:'课题组',dataIndex:'groupName'},{title:'资源',key:'resources',width:150},{title:'状态',key:'status',width:90},{title:'创建时间',dataIndex:'createTime',width:180},{title:'操作',key:'actions',width:300,fixed:'right'}];const statusNames:any={draft:'草稿',in_progress:'进行中',completed:'已完成',archived:'已归档'},statusColors:any={draft:'default',in_progress:'blue',completed:'green',archived:'purple'},recordNames:any={process:'实验过程',result:'实验结果',raw_data:'原始数据',reopen:'退回原因',unarchive:'解档原因'},recordColors:any={process:'blue',result:'green',raw_data:'cyan',reopen:'orange',unarchive:'purple'},statusOptions=Object.entries(statusNames).map(([value,label])=>({value,label})),recordTypes=[{label:'实验过程',value:'process'},{label:'实验结果',value:'result'},{label:'原始数据说明',value:'raw_data'}];const groupOptions=computed(()=>groups.value.map(x=>({label:x.groupName,value:x.id}))),instrumentOptions=computed(()=>instruments.value.map(x=>({label:`${x.instrumentCode} · ${x.instrumentName}`,value:x.id}))),bookingOptions=computed(()=>bookings.value.map(x=>({label:`${x.bookingNo} · ${date(x.startTime)}`,value:x.id,instrumentId:x.instrumentId}))),materialOptions=computed(()=>materials.value.filter(x=>x.isActive).map(x=>({label:`${x.materialCode} · ${x.materialName}`,value:x.id}))),requisitionOptions=computed(()=>requisitions.value.map(x=>({label:x.requisitionNo,value:x.id,materialIds:x.items.map((i:any)=>i.materialId)})));
onMounted(init);watch(()=>props.mode,init);async function init(){await Promise.all([load(),loadRefs()]);}async function load(){loading.value=true;try{rows.value=await experimentApi.list({mine:mode.value==='mine',keyword:filters.keyword||undefined,status:filters.status,startTime:filters.dates?.[0]?.format('YYYY-MM-DD'),endTime:filters.dates?.[1]?.format('YYYY-MM-DD')});}finally{loading.value=false;}}async function loadRefs(){const [g,i,b,m,r]=await Promise.all([labFoundationApi.groups(undefined,true),instrumentApi.instruments(true),instrumentApi.bookings(true,'approved'),inventoryApi.materials(true),inventoryApi.requisitions(true,'approved')]);groups.value=g;instruments.value=i;bookings.value=b;materials.value=m;requisitions.value=r;}
function reset(){Object.assign(form,{experimentName:'',groupId:undefined,topicName:'',purpose:'',instruments:[],materials:[]});}function openCreate(){editing.value=null;reset();editorOpen.value=true;}function openEdit(value:any){const x=value as ExperimentDto;editing.value=x;reset();Object.assign(form,{experimentName:x.experimentName,groupId:x.groupId||undefined,topicName:x.topicName||'',purpose:x.purpose,instruments:x.instruments.map(i=>({instrumentId:i.instrumentId,bookingId:i.bookingId||undefined})),materials:x.materials.map(i=>({materialId:i.materialId,requisitionId:i.requisitionId||undefined,quantity:i.quantity}))});editorOpen.value=true;}async function save(){const payload={experimentName:form.experimentName,groupId:form.groupId,topicName:form.topicName,purpose:form.purpose,instruments:form.instruments.filter((x:any)=>x.instrumentId),materials:form.materials.filter((x:any)=>x.materialId)};editing.value?await experimentApi.update(editing.value.id,payload):await experimentApi.create(payload);message.success('实验任务已保存');editorOpen.value=false;await load();}
function editable(value:any){const x=value as ExperimentDto;return mode.value==='mine'||auth.hasPermission('lab:experiment:unarchive');}async function openDetail(value:any){const x=value as ExperimentDto;detail.value=await experimentApi.detail(x.id);detailOpen.value=true;}async function action(value:any,fn:()=>Promise<any>,text:string){const x=value as ExperimentDto;await fn();message.success(text);await load();if(detail.value?.id===x.id)detail.value=await experimentApi.detail(x.id);}async function start(value:any){const x=value as ExperimentDto;await action(x,()=>experimentApi.start(x.id),'实验已开始');}async function complete(value:any){const x=value as ExperimentDto;await action(x,()=>experimentApi.complete(x.id),'实验已完成');}async function archive(value:any){const x=value as ExperimentDto;Modal.confirm({title:'归档后实验将变为只读，确认归档？',onOk:()=>action(x,()=>experimentApi.archive(x.id),'实验已归档')});}function reasonAction(value:any,type:'reopen'|'unarchive'){const x=value as ExperimentDto;let reason='';Modal.confirm({title:type==='reopen'?'退回进行中':'解档实验',content:()=>h('textarea',{class:'ant-input',rows:4,placeholder:'必须填写原因',onInput:(e:any)=>reason=e.target.value}),onOk:()=>{if(!reason.trim())return Promise.reject();return action(x,()=>type==='reopen'?experimentApi.reopen(x.id,reason):experimentApi.unarchive(x.id,reason),type==='reopen'?'实验已退回':'实验已解档');}});}function openRecord(value:any){const x=value as ExperimentDto;recordTarget.value=x;Object.assign(recordForm,{recordType:'process',content:''});recordOpen.value=true;}async function saveRecord(){await experimentApi.addRecord(recordTarget.value!.id,recordForm);message.success('实验记录已添加');recordOpen.value=false;await load();}async function upload(file:File){await experimentApi.upload(detail.value!.id,file);message.success('附件上传成功');detail.value=await experimentApi.detail(detail.value!.id);return false;}function has(code:string){return auth.hasPermission(code);}function date(v?:string|null){return v?new Date(v).toLocaleString('zh-CN'):'-';}function fileSize(v:number){return v<1024*1024?`${Math.max(v/1024,0.1).toFixed(1)} KB`:`${(v/1024/1024).toFixed(1)} MB`;}function fileType(name:string){const ext=name.split('.').pop()?.toUpperCase();return ext||'文件';}
</script>
<style scoped>
